CREATE TABLE IF NOT EXISTS ${gold_catalog}.sales.FactNewBusiness (
    FactNewBusiness_SK   BIGINT NOT NULL COMMENT 'Surrogate key of FactNewBusiness (-1 is the unknown member).',
    Policy_BK            VARCHAR(20) NOT NULL COMMENT 'Policy number.',
    DimAgent_SK          BIGINT COMMENT 'Writing agent version valid on the issue date (-1 unknown).',
    ProductCode          VARCHAR(20) COMMENT 'Product code.',
    AnnualPremiumAmount  DECIMAL(18,2) COMMENT 'Annualised premium in policy currency.',
    IssueDate            DATE COMMENT 'Date the policy was issued.',
    InsertLoadStepID     STRING NOT NULL COMMENT 'Load step that first wrote the row (the job run id).',
    InsertTimestamp      TIMESTAMP NOT NULL COMMENT 'When the row was first written (UTC).',
    LastUpdateLoadStepID STRING NOT NULL COMMENT 'Load step that last changed the row (the job run id).',
    LastUpdateTimestamp  TIMESTAMP NOT NULL COMMENT 'When the row was last changed (UTC).',
