    CONSTRAINT FactNewBusiness_DimAgent_SK_fk FOREIGN KEY (DimAgent_SK) REFERENCES ${gold_catalog}.distribution.DimAgent (DimAgent_SK)
)
USING DELTA
COMMENT 'One row per issued new business policy. Grain = Policy_BK.';
-- GO

